package tech.wenisch.smtp2x.service;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.ObjectNode; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import tech.wenisch.smtp2x.domain.*; import tech.wenisch.smtp2x.repository.ActionConfigurationRepository;
@Service public class ActionConfigurationService {private final ActionConfigurationRepository actions;private final ObjectMapper json;private final SecretCipher cipher;private final AuditService audit;public ActionConfigurationService(ActionConfigurationRepository a,ObjectMapper j,SecretCipher c,AuditService au){actions=a;json=j;cipher=c;audit=au;}@Transactional public ActionConfiguration save(UUID id,String name,ActionType type,boolean enabled,JsonNode config,String actor){validate(type,config);ObjectNode secured=(ObjectNode)config.deepCopy();encrypt(secured,"accessToken");encrypt(secured,"bearerToken");encrypt(secured,"basicPassword");String value;try{value=json.writeValueAsString(secured);}catch(Exception e){throw new IllegalArgumentException("Invalid action configuration",e);}ActionConfiguration action=id==null?new ActionConfiguration(name,type,value):actions.findById(id).orElseThrow();if(id!=null&&action.getType()!=type)throw new IllegalArgumentException("An action type cannot be changed");if(id!=null)action.update(name,enabled,value);action=actions.save(action);audit.record(actor,id==null?"ACTION_CREATED":"ACTION_UPDATED","action",action.getId().toString(),action.getName());return action;}public JsonNode publicConfiguration(ActionConfiguration action){try{ObjectNode node=(ObjectNode)json.readTree(action.getConfigurationJson());redact(node,"accessToken");redact(node,"bearerToken");redact(node,"basicPassword");return node;}catch(Exception e){throw new IllegalStateException(e);}}private void encrypt(ObjectNode node,String field){if(node.hasNonNull(field)){String value=node.path(field).asText();if(!value.isBlank()&&!value.startsWith("enc:"))node.put(field,cipher.encrypt(value));}}private void redact(ObjectNode node,String field){if(node.has(field)){node.put(field,"");node.put(field+"Configured",true);}}private void validate(ActionType type,JsonNode c){if(!c.isObject())throw new IllegalArgumentException("Action configuration must be an object");if(type==ActionType.GITLAB_ISSUE){for(String f:List.of("baseUrl","project"))if(c.path(f).asText().isBlank())throw new IllegalArgumentException("GitLab action requires "+f);}else if(c.path("url").asText().isBlank())throw new IllegalArgumentException("Webhook action requires url");}}
